promptUsernameAndPassword(
  aDialogTitle,
  aText,
  aPasswordRealm,
  aSavePassword,
  aUsername,
  aPassword
) {
  let finished = false;
  let result = false;
  this.#promptUsernameAndPasswordInternal(
    aDialogTitle,
    aText,
    aPasswordRealm,
    aSavePassword,
    aUsername,
    aPassword
  )
    .then(ok => (result = ok))
    .finally(() => (finished = true));
  Services.tm.spinEventLoopUntilOrQuit(
    "MsgAuthPrompt:promptUsernameAndPassword",
    () => finished
  );
  return result;
}

